with joined as (select a.id, a.session_id, a.event_time, a.duration_sec, p.country from web_events a left join sessions p on a.session_id = p.id), enriched as (select e.*, d.device from joined e left join sessions d on e.session_id = d.id where d.country not in ('JP', 'DE')), with_dims as (select e.id, e.session_id, e.country, b.country as session_country from enriched e left join sessions b on e.session_id = b.id), with_dims_web_events as (select e.*, b.device, b.country as session_country_2, b.browser from with_dims e inner join sessions b on e.session_id = b.id) select session_id, browser, sort_array(collect_set(device)) as device_list, sort_array(collect_set(browser)) as browser_list, count(distinct session_country_2) as distinct_session_country_2s, size(collect_set(session_country)) as num_session_countries, count(distinct session_country_2) as distinct_session_country_2s_2 from with_dims_web_events group by session_id, browser
